             <div className="k3-secondary" data-testid="practice-dashboard-secondary">
             {weakChips.length > 0 ? (
               <div className="lexicon-weak-areas" data-testid="practice-weak-areas">
                 <div
                   className="lexicon-weak-chips"
                   role="group"
