             ) : null}
           </p>
           <PracticeFormRail
             source={{
               label: `${displayPracticeForm(item.lemma, learnerLevel)} / ${displayPracticeForm(item.confusable, learnerLevel)}`,
               value: displayPracticeForm(item.lemma, learnerLevel),
             }}
             actual={{
