         index: [{
           lemmaId: entry.lemmaId,
           lemma: entry.lemma,
           cefr: 'A1',
           modes: ['stress'],
           hasCloze: false,
           clozeIds: [],
           newOrder: 0,
         }],
         cloze: [],
         stress: [{
           stressId: 'stress-n',
           lemmaId: 'stress-fixture',
           lemma: word,
           stressed: word,
           unstressed: word,
           stressIndex,
           nuclei,
           source: 'fixture',
