      margin-top: 38px;
    }
    .track-inventory-grid {
      display: grid;
      grid-template-columns: minmax(260px, 0.75fr) minmax(0, 1.25fr);
      gap: 18px;
      align-items: start;
    }
    .track-column {
      border: 1px solid var(--lu-border);
      border-radius: var(--lu-radius);
      background: var(--lu-surface-raised);
      box-shadow: var(--lu-shadow);
      overflow: hidden;
    }
    .track-column h3 {
      margin: 0;
      padding: 14px 16px;
      border-bottom: 1px solid var(--lu-border);
      color: var(--lu-blue);
      font-size: 0.96rem;
    }
    .track-column ul {
      display: grid;
      gap: 0;
      margin: 0;
      padding: 0;
      list-style: none;
    }
    .track-column li {
      display: grid;
      grid-template-columns: minmax(92px, 0.38fr) minmax(130px, 0.72fr) minmax(150px, 0.74fr);
      gap: 10px;
      align-items: center;
      padding: 11px 16px;
      border-bottom: 1px solid var(--lu-border);
      font-size: 0.86rem;
    }
    .track-column li:last-child {
      border-bottom: 0;
    }
    .track-code {
      color: var(--lu-blue);
      font-weight: 900;
      white-space: nowrap;
    }
    .track-title {
      color: var(--lu-gray-900);
      font-weight: 700;
    }
    .track-meta {
      color: var(--lu-gray-600);
      font-size: 0.8rem;
      text-align: right;
    }
    /* Clickable seminar rows (e.g. the Folklore preview) keep the parent
       grid layout via display:contents so the three columns still align. */
    .track-link {
      display: contents;
      cursor: pointer;
    }
    .track-link:hover .track-title {
      color: var(--lu-blue);
      text-decoration: underline;
    }
    @media (max-width: 820px) {
      .home-intro {
        grid-template-columns: 1fr;
      }
      .home-intro h2 {
        font-size: 1.55rem;
      }
      .track-inventory-grid {
        grid-template-columns: 1fr;
      }
      .track-column li {
        grid-template-columns: 1fr;
        gap: 2px;
      }
      .track-meta {
        text-align: left;
      }
    }
  </style>
</CourseLayout>

