---
import '../styles/course.css';
import ChromeText from '../components/chrome/ChromeText.astro';
import type { ChromeKey } from '../lib/i18n/chrome';

type NavItem = {
  href: string;
  label: string;
};

type SidebarLink = {
  href: string;
  label: string;
  num: string;
  active: boolean;
};

type Sidebar = {
  backHref: string;
  backLabel: string;
  positionLabel: string;
  positionLabelEn?: string;
  titleLabel?: string;
  navLabel?: string;
  progressDone: number;
  progressTotal: number;
  links: SidebarLink[];
};

type Props = {
  title: string;
  description?: string;
  eyebrow?: string;
  eyebrowKey?: ChromeKey;
  subtitle?: string;
  currentPath?: string;
  heroVariant?: 'core' | 'folk' | 'lexicon' | 'seminar' | 'lit' | 'history' | 'readings' | 'unavailable';
  wide?: boolean;
  navItems?: NavItem[];
  sidebar?: Sidebar;
  showHero?: boolean;
};

const {
  title,
  description,
  eyebrow = 'Learn Ukrainian',
  eyebrowKey,
  subtitle = description,
  currentPath = '/',
  heroVariant = 'core',
  wide = false,
  navItems = [],
  sidebar,
  showHero = true,
} = Astro.props as Props;

const sidebarPct =
  sidebar && sidebar.progressTotal > 0
    ? Math.round((sidebar.progressDone / sidebar.progressTotal) * 100)
    : 0;

const canonicalPath = currentPath.endsWith('/') ? currentPath : `${currentPath}/`;

const topNav: { href: string; key: ChromeKey }[] = [
  { href: '/', key: 'nav.home' },
  { href: '/a1/', key: 'nav.a1' },
  { href: '/a2/', key: 'nav.a2' },
  { href: '/b1/', key: 'nav.b1' },
  { href: '/b2/', key: 'nav.b2' },
  { href: '/words-of-the-day/', key: 'nav.dailyWords' },
  { href: '/lexicon/', key: 'nav.atlas' },
  { href: '/readings/', key: 'nav.readings' },
];

const isActive = (href: string) => {
  if (href === '/') return canonicalPath === '/';
  return canonicalPath.startsWith(href);
};
