<!doctype html>
<html lang="en" data-chrome-locale="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="color-scheme" content="light dark" />
    <title>{title} · Learn Ukrainian</title>
    {description && <meta name="description" content={description} />}
    <link rel="icon" href="/favicon.svg" />
    <slot name="head" />
    <script is:inline>
      (() => {
        const query = window.matchMedia('(prefers-color-scheme: dark)');
        const params = new URLSearchParams(window.location.search);
        const requestedTheme = params.get('theme');
        const isTheme = (value) => value === 'dark' || value === 'light';
        const storedTheme = (() => {
          try {
            return window.localStorage.getItem('lu-theme');
          } catch {
            return null;
          }
        })();
        const applyTheme = () => {
          const explicitTheme = isTheme(requestedTheme) ? requestedTheme : isTheme(storedTheme) ? storedTheme : null;
          document.documentElement.dataset.theme = explicitTheme ?? (query.matches ? 'dark' : 'light');
        };
        if (isTheme(requestedTheme)) {
          try {
            window.localStorage.setItem('lu-theme', requestedTheme);
          } catch {
            // Storage can be unavailable in hardened browser contexts.
          }
        }
        applyTheme();
        query.addEventListener?.('change', applyTheme);
        // Manual dark/light toggle (delegated so it works regardless of when
        // the button mounts). Persists to the same `lu-theme` key the loader reads.
        document.addEventListener('click', (event) => {
          const toggle = event.target.closest?.('#lu-theme-toggle');
          if (!toggle) return;
          const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
          document.documentElement.dataset.theme = next;
          try {
            window.localStorage.setItem('lu-theme', next);
          } catch {
            // Storage can be unavailable in hardened browser contexts.
          }
        });
      })();
    </script>
    <script is:inline>
      {/* Chrome Locale Runtime (#3671): pick the UI-chrome language BEFORE paint.
          Precedence: explicit toggle choice (localStorage) → browser locale
          (uk* → Ukrainian) → English fallback. CONTENT stays Ukrainian always;
          this only swaps interface chrome. FOUC-safe: sets the attribute the
          dual-render CSS keys off, before first paint. */}
      (() => {
        const KEY = 'lu-chrome-locale';
        const norm = (value) => (value === 'uk' || value === 'en' ? value : null);
        const stored = (() => {
          try {
            return norm(window.localStorage.getItem(KEY));
          } catch {
            return null;
          }
        })();
        const detect = () => {
          if (stored) return stored;
          const langs =
            navigator.languages && navigator.languages.length
              ? navigator.languages
              : [navigator.language || ''];
          const primary = String(langs[0] || '').toLowerCase().split('-')[0];
          return primary === 'uk' ? 'uk' : 'en';
        };
        document.documentElement.dataset.chromeLocale = detect();
        // Delegated toggle — works regardless of when the button mounts.
        document.addEventListener('click', (event) => {
          const toggle = event.target.closest?.('#lu-locale-toggle');
          if (!toggle) return;
          const next = document.documentElement.dataset.chromeLocale === 'uk' ? 'en' : 'uk';
          document.documentElement.dataset.chromeLocale = next;
          try {
            window.localStorage.setItem(KEY, next);
          } catch {
            // Storage can be unavailable in hardened browser contexts.
          }
        });
      })();
    </script>
    {/* Analytics: self-hosted GoatCounter, injected globally from astro.config.mjs (/count.js).
        Third-party Plausible was removed 2026-06-12 — consolidated to one privacy-friendly, self-hosted analytics. */}
    <style is:global>
      .lu-theme-toggle {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 34px;
        height: 34px;
        margin-left: 0.25rem;
        padding: 0;
        border: 1px solid var(--lu-border, color-mix(in srgb, currentColor 22%, transparent));
        border-radius: 8px;
        background: transparent;
        color: inherit;
        cursor: pointer;
        font-size: 15px;
        line-height: 1;
      }
      .lu-theme-toggle:hover {
        background: var(--lu-surface-muted, rgba(127, 127, 127, 0.14));
      }
      .lu-theme-icon { pointer-events: none; }
      .lu-theme-icon--sun { display: none; }
      .lu-theme-icon--moon { display: inline; }
      [data-theme='dark'] .lu-theme-icon--moon { display: none; }
      [data-theme='dark'] .lu-theme-icon--sun { display: inline; }

      /* Chrome Locale Runtime (#3671) — dual-render show/hide. Default (no
         attribute / English) shows the English variant; the Ukrainian variant
         appears only when chrome-locale=uk. No FOUC: the pre-paint script sets
         data-chrome-locale before first paint. */
      .lu-i18n [data-loc='uk'] { display: none; }
      html[data-chrome-locale='uk'] .lu-i18n [data-loc='uk'] { display: inline; }
      html[data-chrome-locale='uk'] .lu-i18n [data-loc='en'] { display: none; }

      /* Block-level sibling (headings, paragraphs) — same locale rule as .lu-i18n. */
      .lu-i18n-block [data-loc='uk'] { display: none; }
      html[data-chrome-locale='uk'] .lu-i18n-block [data-loc='uk'] { display: block; }
      html[data-chrome-locale='uk'] .lu-i18n-block [data-loc='en'] { display: none; }

      .lu-locale-toggle {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 34px;
        height: 34px;
        margin-left: 0.25rem;
        padding: 0 0.45rem;
        border: 1px solid var(--lu-border, color-mix(in srgb, currentColor 22%, transparent));
        border-radius: 8px;
        background: transparent;
        color: inherit;
        cursor: pointer;
        font-size: 12px;
        font-weight: 600;
        line-height: 1;
        letter-spacing: 0.02em;
      }
      .lu-locale-toggle:hover {
        background: var(--lu-surface-muted, rgba(127, 127, 127, 0.14));
      }
      .lu-locale-label { pointer-events: none; }
      .lu-locale-label[data-loc-when='uk'] { display: none; }
      html[data-chrome-locale='uk'] .lu-locale-label[data-loc-when='uk'] { display: inline; }
      html[data-chrome-locale='uk'] .lu-locale-label[data-loc-when='en'] { display: none; }
    </style>
  </head>
  <body>
    <div class="lu-shell">
      <a class="lu-skip-link" href="#main-content"><ChromeText k="a11y.skip" /></a>
      <header class="lu-header">
        <div class="lu-header-inner">
          <a class="lu-logo" href="/" aria-label="Learn Ukrainian home">
            <span class="lu-logo-mark">LU</span>
            <span>Learn Ukrainian</span>
          </a>
          <nav class="lu-nav" aria-label="Primary">
            {topNav.map((item) => (
              <a href={item.href} aria-current={isActive(item.href) ? 'page' : undefined}>
                <ChromeText k={item.key} />
              </a>
            ))}
            <span class="lu-nav-divider" aria-hidden="true"></span>
            <a href="https://github.com/learn-ukrainian/learn-ukrainian.github.io">GitHub</a>
            <button id="lu-theme-toggle" class="lu-theme-toggle" type="button" aria-label="Toggle dark and light theme" title="Toggle dark / light theme">
              <span class="lu-theme-icon lu-theme-icon--moon" aria-hidden="true">🌙</span>
              <span class="lu-theme-icon lu-theme-icon--sun" aria-hidden="true">☀️</span>
            </button>
            <button id="lu-locale-toggle" class="lu-locale-toggle" type="button" aria-label="Switch interface language (English / Ukrainian)" title="Interface language — English / Ukrainian">
              <span class="lu-locale-label" data-loc-when="en" aria-hidden="true">УКР</span><span class="lu-locale-label" data-loc-when="uk" aria-hidden="true">ENG</span>
            </button>
          </nav>
          <details class="lu-mobile-menu">
            <summary aria-label="Open navigation"><ChromeText k="nav.menu" /></summary>
            <nav aria-label="Mobile primary">
              {topNav.map((item) => (
                <a href={item.href} aria-current={isActive(item.href) ? 'page' : undefined}>
                  <ChromeText k={item.key} />
                </a>
              ))}
              <a href="https://github.com/learn-ukrainian/learn-ukrainian.github.io">GitHub</a>
            </nav>
          </details>
        </div>
      </header>

      <main id="main-content" class="lu-main" tabindex="-1">
        {showHero && (
          <section class:list={[
            'lu-hero',
            heroVariant === 'folk' && 'folk',
            heroVariant === 'lexicon' && 'lexicon',
            heroVariant === 'seminar' && 'seminar',
            heroVariant === 'lit' && 'lit',
            heroVariant === 'history' && 'history',
            heroVariant === 'readings' && 'readings',
            heroVariant === 'unavailable' && 'unavailable',
          ]}>
            <div class="lu-hero-inner">
              <span class="lu-badge">{eyebrowKey ? <ChromeText k={eyebrowKey} /> : eyebrow}</span>
              <h1>{title}</h1>
              {subtitle && <p>{subtitle}</p>}
            </div>
          </section>
        )}

        {navItems.length > 0 && (
          <nav class="lu-breadcrumbs" aria-label="Course navigation">
            {navItems.map((item, index) => (
              <>
                {index > 0 && <span>/</span>}
                <a href={item.href}>{item.label === 'Home' ? <ChromeText k="nav.home" /> : item.label}</a>
              </>
            ))}
          </nav>
        )}

        <article class:list={['lu-page', wide && 'wide', sidebar && 'has-sidebar']}>
          {sidebar && (
            <details class="lu-sidebar" open>
              <summary class="lu-sidebar-toggle">
                {sidebar.titleLabel ? sidebar.titleLabel : <ChromeText k="sidebar.lessons" />} · <span class="lu-i18n"><span data-loc="en">{sidebar.positionLabelEn ?? sidebar.positionLabel}</span><span data-loc="uk">{sidebar.positionLabel}</span></span>
              </summary>
              <div class="lu-sidebar-body">
                <a class="lu-sidebar-back" href={sidebar.backHref}>← {sidebar.backLabel}</a>
                <div class="lu-sidebar-progress">
                  <div><span class="lu-i18n"><span data-loc="en">{sidebar.positionLabelEn ?? sidebar.positionLabel}</span><span data-loc="uk">{sidebar.positionLabel}</span></span></div>
                  <div class="lu-mini-bar">
                    <div class="lu-mini-fill" style={`width:${sidebarPct}%`} />
                  </div>
                </div>
                <nav class="lu-sidebar-nav" aria-label={sidebar.navLabel ?? 'Уроки цього рівня'}>
                  {sidebar.links.map((link) => (
                    <a
                      class:list={['lu-sidebar-link', link.active && 'active']}
                      href={link.href}
                      aria-current={link.active ? 'page' : undefined}
                    >
                      <span class="lu-sidebar-num">{link.num}</span>
                      <span class="lu-sidebar-text">{link.label}</span>
                    </a>
                  ))}
