    state: 'planned',
    heroVariant: 'seminar',
    primaryAction: { href: '/etymology/', label: 'Open Etymology' },
    points: [
      'OES is not a beginner lane; it needs a denser reference-first reading surface.',
      'The template reserves space for paleography, glossary, and evidence blocks.',
      'Reference links should support, not replace, guided seminar interpretation.',
    ],
    pattern: ['dense reading', 'glossary', 'paleography note', 'evidence table'],
  },
  ruth: {
    label: 'RUTH',
    title: 'RUTH · Ruthenian Baroque',
    eyebrow: 'Planned seminar track',
    subtitle: 'Historical-language and baroque text work needs glossary support, context, and source trails.',
    status: 'Planned seminar work',
    family: 'seminar',
    state: 'planned',
    heroVariant: 'seminar',
    primaryAction: { href: '/etymology/', label: 'Open Etymology' },
    points: [
      'RUTH will use the historical-language seminar surface, not the core lesson ladder.',
      'The planned template emphasizes context, terms, source notes, and careful quotation boundaries.',
      'The current page is an honest unavailable/planned landing for future work.',
    ],
    pattern: ['context frame', 'glossary', 'source note', 'evidence table'],
  },
};

const HIDDEN_DOCS = new Set(['a1/review-clears-needs-human']);
// Folk un-hidden 2026-06-19: 6 modules are e2e-certified and folk is already
// public (astro.config hiddenPublicPaths=[]); this completes the nav un-hide so
// folk module pages get their left sidebar + breadcrumbs + search (reverses #3027 —
// coordinate with orchestrator on the launch posture).
const HIDDEN_LINK_TRACKS = new Set<string>();
const SEARCH_LESSON_PREFIXES = new Set(['a1', 'a2']);
const normalizeId = (id: string) => id.replace(/\.mdx?$/, '').replace(/\/index$/, '');
const hrefFromRoute = (route: string) => `/${route}/`;
const trackIds = Object.keys(TRACKS);
const searchTrackIds = trackIds.filter((id) => !HIDDEN_LINK_TRACKS.has(id));

const allDocs = await getCollection('docs');
// Хрестоматія readings — surfaced in site-wide search like Word Atlas entries.
const allReadings = (await getCollection('readings')).filter(isPublishedReading);
const visibleDocs = allDocs.filter((entry) => {
  const id = normalizeId(entry.id);
  const track = id.split('/')[0];
  if (HIDDEN_DOCS.has(id)) return false;
  if (entry.data.draft) return false;
  return track in TRACKS || (id !== 'index' && id === track);
});

const deployedDocsByTrack = new Map<string, DocsEntry[]>();
const landingDocsByTrack = new Map<string, DocsEntry>();
for (const entry of visibleDocs) {
  const id = normalizeId(entry.id);
  const track = id.split('/')[0];
  if (id === track) {
    landingDocsByTrack.set(track, entry);
    continue;
  }
  const bucket = deployedDocsByTrack.get(track) ?? [];
  bucket.push(entry);
  deployedDocsByTrack.set(track, bucket);
}
for (const entries of deployedDocsByTrack.values()) {
  entries.sort((a, b) => (a.data.sidebar?.order ?? 999) - (b.data.sidebar?.order ?? 999));
}

const searchItems: SearchItem[] = [
  ...searchTrackIds.map((id) => {
    const track = TRACKS[id];
    return {
      title: `${track.label} · ${track.title}`,
      href: `/${id}/`,
      type: track.family === 'core' ? 'Core track' : 'Seminar track',
      track: track.label,
      text: `${track.subtitle} ${track.status} ${track.points.join(' ')} ${track.pattern.join(' ')}`,
    };
  }),
  ...visibleDocs
    .filter((entry) => {
      const id = normalizeId(entry.id);
      const track = id.split('/')[0];
      return SEARCH_LESSON_PREFIXES.has(track) && id !== track;
    })
    .map((entry) => {
      const id = normalizeId(entry.id);
      const track = id.split('/')[0];
      return {
        title: entry.data.title,
        href: hrefFromRoute(id),
        type: track === 'folk' ? 'Seminar lesson' : 'Core lesson',
        track: TRACKS[track]?.label ?? track.toUpperCase(),
        text: `${entry.data.title} ${entry.data.description ?? ''} ${entry.data.sidebar?.label ?? ''}`,
      };
    }),
  ...lexicon.slice(0, 160).map((entry) => ({
    title: entry.l,
    href: `/lexicon/${entry.s}/`,
    type: 'Word Atlas',
    track: 'Atlas',
    text: `${entry.l} ${entry.g ?? ''}`,
  })),
  ...allReadings.map((entry) => ({
    title: entry.data.title,
    href: `/readings/${entry.id}/`,
    type: 'Reading reference',
    track: 'Reference',
    text: `${entry.data.title} ${entry.data.title_en ?? ''} ${entry.data.genre} ${entry.data.author ?? ''} ${entry.data.excerpt}`,
  })),
  {
    title: 'Етимологія',
    href: '/etymology/',
    type: 'Reference',
    track: 'Reference',
    text: 'ЕСУМ etymology reference entries cognates proto forms source dictionary',
  },
];

export async function getStaticPaths() {
  const normalizeDocId = (id: string) => id.replace(/\.mdx?$/, '').replace(/\/index$/, '');
  const publicLessonPrefixes = new Set(['a1', 'a2', 'b1', 'b2', 'bio', 'folk']);
  const hiddenDocs = new Set(['a1/review-clears-needs-human']);
  const configuredTracks = ['a1', 'a2', 'b1', 'b2', 'c1', 'c2', 'folk', 'bio', 'hist', 'istorio', 'lit', 'oes', 'ruth'];
  const pathDocs = await getCollection('docs');
  const landingDocsByPathTrack = new Map<string, DocsEntry>();
  const docs = pathDocs.filter((entry) => {
    const id = normalizeDocId(entry.id);
    const track = id.split('/')[0];
    if (id !== 'index' && id === track) {
      landingDocsByPathTrack.set(track, entry);
      return false;
    }
    if (!publicLessonPrefixes.has(track)) return false;
    if (hiddenDocs.has(id)) return false;
    if (entry.data.draft) return false;
    return true;
  });
  const tracks = [...new Set([...configuredTracks, ...landingDocsByPathTrack.keys()])];

  return [
    ...tracks.map((track) => ({
      params: { slug: track },
      props: landingDocsByPathTrack.has(track)
        ? { kind: 'landingDoc', entry: landingDocsByPathTrack.get(track)! }
        : { kind: 'track', track },
    })),
    { params: { slug: 'search' }, props: { kind: 'search' } },
    { params: { slug: 'missing-content' }, props: { kind: 'state', state: 'missing-content' } },
    { params: { slug: 'empty-reference' }, props: { kind: 'state', state: 'empty-reference' } },
    ...docs.map((entry) => ({
      params: { slug: normalizeDocId(entry.id) },
      props: { kind: 'doc', entry },
    })),
  ];
}

const props = Astro.props as RouteProps;
const pageTrack = props.kind === 'track'
  ? TRACKS[props.track]
  : props.kind === 'landingDoc'
    ? TRACKS[normalizeId(props.entry.id).split('/')[0]]
  : props.kind === 'doc'
    ? TRACKS[normalizeId(props.entry.id).split('/')[0]]
    : undefined;

let Content: Awaited<ReturnType<typeof render<'docs'>>>['Content'] | undefined;
let docRoute = '';
let docTrack = '';
let isSeminarLesson = false;
let previousLink: { href: string; label: string } | undefined;
let nextLink: { href: string; label: string } | undefined;

if (props.kind === 'doc' || props.kind === 'landingDoc') {
  const rendered = await render(props.entry);
  Content = rendered.Content;
  docRoute = normalizeId(props.entry.id);
  docTrack = docRoute.split('/')[0];
  isSeminarLesson = TRACKS[docTrack]?.family === 'seminar';
  if (props.kind === 'doc') {
    const prev = props.entry.data.prev;
    const next = props.entry.data.next;
    if (!HIDDEN_LINK_TRACKS.has(docTrack)) {
      if (typeof prev === 'string') previousLink = { href: `/${docTrack}/${prev}/`, label: 'Previous' };
      if (typeof next === 'string') nextLink = { href: `/${docTrack}/${next}/`, label: 'Next' };
    }
  }
}

const pageMeta = (() => {
  if (props.kind === 'track') {
    const track = TRACKS[props.track];
    return {
      title: track.title,
      description: track.subtitle,
      eyebrow: track.eyebrow,
      subtitle: track.subtitle,
      currentPath: `/${props.track}/`,
      heroVariant: track.heroVariant,
      wide: true,
    };
  }
  if (props.kind === 'landingDoc') {
    const route = normalizeId(props.entry.id);
    const track = route.split('/')[0];
    return {
      title: props.entry.data.title,
      description: props.entry.data.description ?? TRACKS[track]?.subtitle,
      eyebrow: TRACKS[track]?.eyebrow ?? `${track.toUpperCase()} landing`,
      subtitle: props.entry.data.description ?? TRACKS[track]?.subtitle,
      currentPath: hrefFromRoute(route),
      heroVariant: TRACKS[track]?.heroVariant ?? 'core',
      wide: true,
    };
  }
  if (props.kind === 'search') {
    return {
      title: 'Search',
      description: 'Search the learner UI, course lessons, track landings, Word Atlas entries, and reference pages.',
      eyebrow: 'Find a page',
      subtitle: 'Static client-side search for lessons, tracks, Word Atlas entries, and references.',
      currentPath: '/search/',
      heroVariant: 'lexicon' as HeroVariant,
      wide: true,
    };
  }
  if (props.kind === 'state') {
    const title = props.state === 'not-found'
      ? 'Page Not Found'
      : props.state === 'missing-content'
        ? 'Missing Content'
        : 'Empty Reference State';
    return {
      title,
      description: 'Learner UI state template for missing, unavailable, and empty content.',
      eyebrow: 'Learner state',
      subtitle: 'A clear route state keeps learners oriented instead of dropping them into a generic docs page.',
      currentPath: props.state === 'not-found' ? '/404/' : `/${props.state}/`,
      heroVariant: 'unavailable' as HeroVariant,
      wide: true,
    };
  }

  const route = normalizeId(props.entry.id);
  const track = route.split('/')[0];
  const order = props.entry.data.sidebar?.order;
  return {
    title: props.entry.data.title,
    description: props.entry.data.description ?? TRACKS[track]?.subtitle,
    eyebrow: `${TRACKS[track]?.label ?? track.toUpperCase()} · ${order ? `Module ${String(order).padStart(2, '0')}` : 'Lesson'}`,
    subtitle: props.entry.data.description ?? TRACKS[track]?.subtitle,
    currentPath: hrefFromRoute(route),
    heroVariant: TRACKS[track]?.heroVariant ?? 'core',
    wide: false,
  };
})();

const currentTrackId = props.kind === 'track' ? props.track : docTrack;
const navItems = HIDDEN_LINK_TRACKS.has(currentTrackId)
  ? [{ href: '/', label: 'Home' }]
  : props.kind === 'doc'
  ? [
      { href: '/', label: 'Home' },
      { href: `/${docTrack}/`, label: TRACKS[docTrack]?.label ?? docTrack.toUpperCase() },
      { href: hrefFromRoute(docRoute), label: props.entry.data.sidebar?.label ?? props.entry.data.title },
    ]
  : props.kind === 'landingDoc'
    ? [
        { href: '/', label: 'Home' },
        { href: hrefFromRoute(docRoute), label: TRACKS[docTrack]?.label ?? props.entry.data.title },
      ]
  : [
      { href: '/', label: 'Home' },
      { href: pageMeta.currentPath, label: pageMeta.title },
    ];

// Doc-layout lesson sidebar (#2823): persistent track navigation built from the
// same per-track sorted lesson list the track landing page uses.
const sidebar = props.kind === 'doc'
  ? (() => {
      if (HIDDEN_LINK_TRACKS.has(docTrack)) return undefined;
      const lessons = deployedDocsByTrack.get(docTrack) ?? [];
      if (lessons.length === 0) return undefined;
      const links = lessons.map((entry) => {
        const id = normalizeId(entry.id);
        const order = entry.data.sidebar?.order;
        return {
          href: hrefFromRoute(id),
          label: entry.data.title,
          num: order ? String(order).padStart(2, '0') : '•',
          active: id === docRoute,
        };
      });
      const currentIndex = links.findIndex((link) => link.active);
      const position = currentIndex >= 0 ? currentIndex + 1 : 0;
      return {
        backHref: `/${docTrack}/`,
        backLabel: TRACKS[docTrack]?.label ?? docTrack.toUpperCase(),
        // Ukrainian sidebar labels for ALL tracks (immersion rule #M-13) — was
        // gated to b1 only, which leaked English nav text for folk/seminars/core.
        positionLabel: position > 0
          ? `Урок ${position} з ${links.length}`
          : `${links.length} уроки`,
        positionLabelEn: position > 0
          ? `Lesson ${position} of ${links.length}`
          : `${links.length} lessons`,
        titleLabel: 'Уроки',
        navLabel: 'Уроки цього рівня',
        progressDone: position,
        progressTotal: links.length,
        links,
      };
    })()
  : undefined;

const plannedModuleGroups = (track: string, trackOverview: TrackOverview) => {
  const count = moduleCount(track);
  return [{
    unit: `${trackOverview.label} planned modules`,
    items: Array.from({ length: count }, (_, index) => {
      const num = index + 1;
      return {
        num,
        slug: `planned-${String(num).padStart(2, '0')}`,
        title: `Planned module ${String(num).padStart(2, '0')}`,
        sub: 'Mapped curriculum slot; not released for study yet.',
        status: 'locked' as const,
      };
    }),
  }];
};
---

<CourseLayout
  title={pageMeta.title}
  description={pageMeta.description}
  eyebrow={pageMeta.eyebrow}
  subtitle={pageMeta.subtitle}
  currentPath={pageMeta.currentPath}
  heroVariant={pageMeta.heroVariant}
  navItems={navItems}
  sidebar={sidebar}
  wide={pageMeta.wide}
  showHero={props.kind !== 'landingDoc' && props.kind !== 'track'}
>
  {props.kind === 'landingDoc' && Content ? (
    <Content />
  ) : props.kind === 'track' && pageTrack ? (
    <LevelLanding
      client:load
      level={pageTrack.label.toUpperCase()}
      title={pageTrack.title}
      subtitle={pageTrack.subtitle}
      moduleCount={moduleCount(props.track)}
      wordTarget={4000}
      color={`var(--lu-id-${props.track})`}
      modules={plannedModuleGroups(props.track, pageTrack)}
    />
  ) : props.kind === 'search' ? (
    <section class="search-page" data-search-root>
      <form class="search-panel" role="search">
        <label for="course-search"><ChromeText k="search.label" /></label>
        <div class="search-input-row">
          <input id="course-search" name="q" type="search" placeholder={CHROME_STRINGS.en['search.placeholder']} autocomplete="off" />
          <button type="submit"><ChromeText k="nav.search" /></button>
        </div>
      </form>

      <div class="search-state search-loading" data-search-loading hidden>
        <span class="state-code"><ChromeText k="search.loadingCode" /></span>
        <p><ChromeText k="search.loadingBody" /></p>
      </div>
      <div class="search-state search-error" data-search-error hidden>
        <span class="state-code"><ChromeText k="search.errorCode" /></span>
        <h2><ChromeText k="search.errorTitle" /></h2>
        <p><ChromeText k="search.errorBody" /></p>
      </div>
      <div class="search-state search-empty" data-search-empty hidden>
        <span class="state-code"><ChromeText k="search.emptyCode" /></span>
        <h2><ChromeText k="search.emptyTitle" /></h2>
        <p><ChromeText k="search.emptyBody" /></p>
      </div>

      <section class="search-results-section" aria-live="polite">
        <div class="section-heading">
          <h2 data-search-heading><ChromeText k="search.suggested" /></h2>
          <p data-search-count><ChromeText k="search.hint" /></p>
        </div>
        <div class="search-results" data-search-results>
          {searchItems.slice(0, 9).map((item) => (
            <a href={item.href}>
              <span>{item.type} · {item.track}</span>
              <strong>{item.title}</strong>
            </a>
          ))}
        </div>
      </section>

      <script is:inline define:vars={{ searchItems, searchI18n: {
        en: {
          resultsFor: 'Results for',
          suggested: 'Suggested Pages',
          match: 'match',
          matches: 'matches',
          matchesInIndex: 'in the static learner index.',
          noPagesMatched: 'No pages matched this query.',
          hint: 'Start with a broad query or use the shortcuts.',
        },
        uk: {
          resultsFor: 'Результати для',
          suggested: 'Рекомендовані сторінки',
          match: 'збіг',
          matches: 'збігів',
          matchesInIndex: 'у статичному покажчику курсу.',
          noPagesMatched: 'Немає сторінок за цим запитом.',
          hint: 'Почніть із загального запиту або скористайтеся посиланнями.',
        },
      } }}>
        const root = document.querySelector('[data-search-root]');
        const input = root?.querySelector('#course-search');
        const form = root?.querySelector('form');
        const results = root?.querySelector('[data-search-results]');
        const count = root?.querySelector('[data-search-count]');
        const heading = root?.querySelector('[data-search-heading]');
        const empty = root?.querySelector('[data-search-empty]');
        const error = root?.querySelector('[data-search-error]');
        const loading = root?.querySelector('[data-search-loading]');
        const params = new URLSearchParams(window.location.search);
        const locale = () => (document.documentElement.dataset.chromeLocale === 'uk' ? 'uk' : 'en');
        const s = () => searchI18n[locale()];
        const normalize = (value) => String(value || '').toLocaleLowerCase('uk');
        const escapeHtml = (value) => String(value || '')
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;');
        const render = (query) => {
          const q = normalize(query).trim();
          const strings = s();
          error.hidden = params.get('state') !== 'error';
          loading.hidden = true;
          if (!results || !count || !heading || !empty || !error.hidden) return;
          const matches = q
            ? searchItems.filter((item) => normalize(`${item.title} ${item.text} ${item.type} ${item.track}`).includes(q)).slice(0, 24)
            : searchItems.slice(0, 9);
          empty.hidden = matches.length !== 0 || !q;
          heading.textContent = q ? `${strings.resultsFor} "${query}"` : strings.suggested;
          count.textContent = matches.length
            ? `${matches.length} ${matches.length === 1 ? strings.match : strings.matches} ${strings.matchesInIndex}`
            : q
              ? strings.noPagesMatched
              : strings.hint;
          results.innerHTML = matches.map((item) => (
            `<a href="${escapeHtml(item.href)}"><span>${escapeHtml(item.type)} · ${escapeHtml(item.track)}</span><strong>${escapeHtml(item.title)}</strong></a>`
          )).join('');
        };
        if (input) {
          input.value = params.get('q') || '';
          input.addEventListener('input', () => render(input.value));
        }
        form?.addEventListener('submit', (event) => {
          event.preventDefault();
          const query = input?.value || '';
          const url = query ? `/search/?q=${encodeURIComponent(query)}` : '/search/';
          window.history.replaceState(null, '', url);
          render(query);
        });
        render(input?.value || '');
      </script>
    </section>
  ) : props.kind === 'state' ? (
    <section class="route-state-card big">
      <p class="state-code">
        {props.state === 'not-found' ? '404' : props.state === 'missing-content' ? 'Missing' : 'Empty'}
      </p>
      <h2>
        {props.state === 'not-found'
          ? <ChromeText k="state.notFoundTitle" />
          : props.state === 'missing-content'
            ? <ChromeText k="state.missingTitle" />
            : <ChromeText k="state.emptyTitle" />}
      </h2>
      <p>
        {props.state === 'not-found'
          ? <ChromeText k="state.notFoundBody" />
          : props.state === 'missing-content'
            ? <ChromeText k="state.missingBody" />
            : <ChromeText k="state.emptyBody" />}
      </p>
      <div class="state-actions">
        <a href="/a1/"><ChromeText k="nav.a1" /></a>
        <a href="/b1/"><ChromeText k="nav.b1" /></a>
        <a href="/search/"><ChromeText k="nav.search" /></a>
        <a href="/lexicon/"><ChromeText k="nav.atlas" /></a>
      </div>
    </section>
  ) : Content ? (
    <section class:list={['lesson-shell', isSeminarLesson && 'seminar-lesson']}>
      <aside class="lesson-companion" aria-label="Lesson context">
        <p class="state-code">{isSeminarLesson ? <ChromeText k="companion.seminarCode" /> : <ChromeText k="companion.coreCode" />}</p>
        <h2>{isSeminarLesson ? <ChromeText k="companion.seminarTitle" /> : <ChromeText k="companion.coreTitle" />}</h2>
        <p>{isSeminarLesson ? <ChromeText k="companion.seminarBody" /> : <ChromeText k="companion.coreBody" />}</p>
      </aside>
      <Content />
      {(previousLink || nextLink) && (
        <nav class="lesson-next-prev" aria-label="Lesson navigation">
          {previousLink ? <a href={previousLink.href}>← <ChromeText k="label.previous" /></a> : <span></span>}
          {nextLink ? <a href={nextLink.href}><ChromeText k="label.next" /> →</a> : <span></span>}
        </nav>
      )}
    </section>
  ) : null}
</CourseLayout>

